mapper.update:
UPDATE t_user_account SET consecutive_password_failures=0, locked_until=NULL,
last_password_failure_time=NULL, version=version+1, update_time=#{now}
WHERE account_id=#{accountId} AND realm='CUSTOMER' AND account_type='HUMAN' AND status='ACTIVE'
AND email_verified_time IS NOT NULL AND version=#{expectedVersion}
AND credential_version=#{credentialVersion} AND auth_epoch=#{epoch}
AND (locked_until IS NULL OR locked_until<=#{now})

UPDATE t_refresh_token_generation SET status='CONSUMED', active_slot=NULL,
consumed_time=#{now}, version=version+1, update_time=#{now}
WHERE refresh_generation_id=#{id} AND session_id=#{sessionId} AND generation_no=#{generation}
AND status='ISSUED' AND active_slot=1 AND expires_time>#{now}

UPDATE t_auth_session SET current_generation_no=#{issue.generation}, last_activity_time=#{issue.issuedTime},
idle_expire_time=#{issue.idleExpireTime}, version=version+1, update_time=#{issue.issuedTime}
WHERE session_id=#{issue.sessionId} AND realm='CUSTOMER' AND channel='CLIENT' AND status='ACTIVE'
AND version=#{expectedVersion} AND current_generation_no=#{issue.generation}-1
AND account_auth_epoch=#{issue.accountEpoch} AND credential_version_snapshot=#{issue.credentialVersion}

UPDATE t_auth_session SET status=#{status}, revocation_reason=#{reason}, revoked_time=#{now},
version=version+1, update_time=#{now}
WHERE session_id=#{sessionId} AND realm='CUSTOMER' AND channel='CLIENT' AND status='ACTIVE'

UPDATE t_refresh_token_generation r JOIN t_auth_session s ON s.session_id=r.session_id
SET r.status='REVOKED', r.active_slot=NULL, r.version=r.version+1, r.update_time=#{now}
WHERE s.session_id=#{sessionId} AND s.realm='CUSTOMER' AND s.channel='CLIENT' AND r.status='ISSUED'
